pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzzed params: from address, an array of recipient addresses (single recipient to keep recorded calls deterministic), and a uint value
    function testFuzz_property(address from, address to, uint256 v) public {
        // keep addresses non-zero and ensure to != address(0)
        vm.assume(from != address(0));
        vm.assume(to != address(0));

        // prepare single-element array for _tos so the external call happens exactly once
        address[] memory tos = new address[](1);
        tos[0] = to;

        // We will call transfer and observe its returned boolean via try/catch pattern
        bool ok;
        try c.transfer(from, to, tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, consider ok = false (but correct contract does not revert for admissible inputs since require only checks length > 0)
            ok = false;
        }

        // The universal property: reference contract always returns true for any admissible input.
        // The mutant changes the final return to false, so this assertion will fail on the mutant for some inputs.
        assertTrue(ok);
    }
}
